// Arsenal de ejercicios. Generado desde ejercicios.md (cues de Villarroel) + catálogo de free-exercise-db (Unlicense) con fichas en español.
// n nombre · g músculo · lv x lo sé / sin dominar / ' ' por aprender · i id de foto · q búsqueda de YouTube · c técnica · cat 1 = catálogo · p peso inicial
const ARSENAL=[
{"n":"Jalón al pecho, agarre ancho","g":"Espalda","lv":"x","i":"Wide-Grip_Lat_Pulldown","q":"jalon al pecho agarre ancho","c":"Pecho arriba, hombros abajo antes de tirar. Codos hacia los bolsillos, no hacia atrás. La barra llega a la clavícula, no al esternón. Si el cuerpo se va hacia atrás más de 15°, es mucho peso."},
{"n":"Remo en máquina (Mid Row)","g":"Espalda","lv":"x","i":"Leverage_Iso_Row","q":"remo sentado en maquina","p":"5 placas","c":"Pecho pegado al apoyo todo el tiempo. Tira con los codos, no con las manos. Al final aprieta las escápulas un segundo y suelta despacio. Si te despegas del pad, bajas el peso."},
{"n":"Remo con apoyo de pecho","g":"Espalda","lv":"/","i":"Lying_T-Bar_Row","q":"remo en t con apoyo de pecho","c":"Pecho pegado al pad todo el tiempo. Tira con los codos, no con las manos, y llévalos pegados al cuerpo. Aprieta las escápulas un segundo atrás y suelta despacio. Sin tirones con la espalda baja."},
{"n":"Remo con barra","g":"Espalda","lv":"/","i":"Bent_Over_Barbell_Row","q":"remo con barra tecnica","c":"Rodillas suaves, torso a 45°, espalda recta como una mesa. La barra va al ombligo. Primero domina el remo con apoyo de pecho, este viene después."},
{"n":"Remo con mancuerna a un brazo","g":"Espalda","lv":"/","i":"One-Arm_Dumbbell_Row","q":"remo con mancuerna a una mano","c":"Mano y rodilla en el banco, espalda plana. Tira el codo hacia la cadera, no hacia el techo. Pausa arriba. Buen sustituto cuando la máquina está ocupada."},
{"n":"Pullover en polea (barra recta)","g":"Espalda","lv":"/","i":"Straight-Arm_Pulldown","q":"pullover en polea brazos rectos","c":"Brazos casi rectos, codos fijos, baja la barra hasta los muslos. Trabaja el dorsal sin bíceps. No te gusta: se usa solo si falta volumen."},
{"n":"Face pull (polea, cuerda)","g":"Espalda","lv":"/","i":"Face_Pull","q":"face pull polea tecnica","c":"Polea a la altura de la cara. Tira separando las manos, los codos terminan a la altura de los hombros. Peso ligero, 15 reps, sin balancearte. Cuida los hombros de todo lo que empujas."},
{"n":"Encogimientos de trapecio","g":"Espalda","lv":"x","i":"Dumbbell_Shrug","q":"encogimientos de trapecio con mancuernas","c":"Solo arriba y abajo, sin rotar los hombros. Pausa un segundo arriba. Brazos como ganchos, no dobles los codos."},
{"n":"Jalón agarre cerrado (polea)","g":"Espalda","lv":" ","i":"Close-Grip_Front_Lat_Pulldown","q":"jalon al pecho agarre cerrado","c":"Mismo gesto que el jalón ancho, con las manos al ancho de los hombros. Pecho arriba y codos pegados al cuerpo bajando hacia las costillas. Llega a la parte alta del pecho sin echarte atrás."},
{"n":"Dominadas","g":"Espalda","lv":" ","i":"Pullups","q":"dominadas para principiantes","c":"Agarre un poco más ancho que los hombros, cuerpo colgando quieto. Sube llevando el pecho a la barra y los codos hacia las costillas. Si no sale ninguna, empieza en la máquina asistida."},
{"n":"Remo landmine","g":"Espalda","lv":" ","i":"Bent_Over_Two-Arm_Long_Bar_Row","q":"remo landmine con barra","c":"Barra con un extremo fijo en la esquina o landmine, montado sobre ella. Torso a 45°, espalda recta. Tira el disco hacia el pecho bajo con los codos pegados y baja controlado."},
{"n":"Hiperextensiones (banco 45°)","g":"Espalda","lv":" ","i":"Hyperextensions_Back_Extensions","q":"hiperextensiones banco 45 grados","c":"Cadera apoyada justo en el borde del pad. Baja con la espalda recta doblando la cadera y sube hasta que el cuerpo quede en línea, no más arriba. Lento, sin rebotes."},
{"n":"Press banca plano (barra)","g":"Pecho","lv":"x","i":"Barbell_Bench_Press_-_Medium_Grip","q":"press banca plano con barra","c":"Pies firmes, escápulas juntas y pegadas al banco, arco natural. La barra baja al pecho medio en 2 segundos y sube sin rebotar. Codos a 45°, no abiertos a 90°. Sin compañero, no pases de un peso que puedas frenar solo."},
{"n":"Press banca plano (mancuernas)","g":"Pecho","lv":"x","i":"Dumbbell_Bench_Press","q":"press banca plano con mancuernas","c":"Sube las mancuernas con las rodillas al acostarte. Mismo recorrido que la barra, un poco más profundo. Arriba no las choques. Sirve cuando la banca está ocupada."},
{"n":"Press inclinado (barra)","g":"Pecho","lv":"x","i":"Barbell_Incline_Bench_Press_-_Medium_Grip","q":"press inclinado con barra","c":"Banco a 30°, no más. La barra baja a la parte alta del pecho, no al cuello. Mismos codos a 45°."},
{"n":"Press inclinado (mancuernas)","g":"Pecho","lv":"x","i":"Incline_Dumbbell_Press","q":"press inclinado con mancuernas","c":"Banco a 30°. Mancuernas bajan hasta la altura del pecho, codos a 45°. Mejor opción para pecho superior por rango de recorrido."},
{"n":"Pec deck","g":"Pecho","lv":"x","i":"Butterfly","q":"pec deck aperturas en maquina","c":"Asiento a la altura que los agarres queden al medio del pecho. Codos suaves y fijos. Junta al frente apretando el pecho un segundo, abre despacio sin pasar la línea de los hombros."},
{"n":"Chest press (máquina)","g":"Pecho","lv":" ","i":"Leverage_Chest_Press","q":"press de pecho en maquina","c":"Asiento a la altura que los agarres queden al medio del pecho. Espalda pegada, empuja sin bloquear los codos y vuelve despacio hasta sentir el estiramiento. En el Coliseum no hay una buena."},
{"n":"Cruces en polea","g":"Pecho","lv":" ","i":"Cable_Crossover","q":"cruces en polea pecho","c":"Un paso al frente, torso un poco inclinado, codos suaves y fijos. Junta las manos delante del pecho bajo apretando un segundo. Abre controlado sin que los brazos pasen detrás del cuerpo."},
{"n":"Fondos en paralelas","g":"Pecho","lv":" ","i":"Dips_-_Chest_Version","q":"fondos en paralelas para pecho","c":"Torso inclinado hacia adelante y codos un poco abiertos para cargar el pecho. Baja hasta que el hombro quede a la altura del codo, no más. Si cuesta, usa la máquina asistida."},
{"n":"Flexiones","g":"Pecho","lv":" ","i":"Pushups","q":"flexiones de pecho tecnica","c":"Manos un poco más abiertas que los hombros, cuerpo recto de cabeza a talones. Baja hasta casi tocar el piso con el pecho, codos a 45°. Si la cadera se cae, apoya las rodillas."},
{"n":"Press militar sentado (mancuernas)","g":"Hombro","lv":"x","i":"Seated_Dumbbell_Press","q":"press militar con mancuernas sentado","c":"Respaldo a 80-90°. Mancuernas a la altura de las orejas, codos un poco adelante del cuerpo, no abiertos del todo. Sube sin chocarlas arriba. Baja controlado hasta las orejas, no más abajo."},
{"n":"Press de hombro (máquina)","g":"Hombro","lv":"x","i":"Leverage_Shoulder_Press","q":"press de hombro en maquina convergente","c":"Asiento a la altura que los agarres queden a nivel de las orejas al empezar. Espalda pegada. Empuja sin bloquear los codos arriba. Es la opción segura para meter peso."},
{"n":"Elevaciones laterales","g":"Hombro","lv":"x","i":"Side_Lateral_Raise","q":"elevaciones laterales con mancuernas","c":"Codos suaves, sube hasta la altura de los hombros y no más. Meñique un poco más alto que el pulgar. Baja en 2 segundos. Si balanceas el cuerpo, baja el peso. Es de reps, no de kilos."},
{"n":"Elevaciones frontales","g":"Hombro","lv":"x","i":"Front_Dumbbell_Raise","q":"elevaciones frontales con mancuernas","c":"Hasta la altura de los ojos, brazos casi rectos. Alternado o con disco a dos manos. Va de último, el hombro frontal ya trabajó en todos los press."},
{"n":"Reverse fly (máquina)","g":"Hombro","lv":"x","i":"Reverse_Machine_Flyes","q":"reverse fly en maquina deltoides posterior","c":"Pecho al pad, agarres a la altura de los hombros, abre con los codos un poco doblados hasta la línea del cuerpo. Peso ligero, 15 reps. Es lo que equilibra tantos press."},
{"n":"Press militar (barra)","g":"Hombro","lv":" ","i":"Standing_Military_Press","q":"press militar con barra de pie","c":"De pie, glúteo y abdomen apretados para no arquear la espalda. La barra sale de la clavícula y sube en línea recta, la cabeza se aparta y vuelve debajo de la barra. Por ahora no."},
{"n":"Elevaciones laterales en polea","g":"Hombro","lv":" ","i":"Standing_Low-Pulley_Deltoid_Raise","q":"elevacion lateral en polea baja","c":"De lado a la polea baja, agarre con la mano de afuera. Sube hasta la altura del hombro con el codo suave. La polea mantiene la tensión abajo, donde la mancuerna no trabaja."},
{"n":"Curl de bíceps (mancuernas)","g":"Bíceps","lv":"x","i":"Dumbbell_Bicep_Curl","q":"curl de biceps con mancuernas","c":"Codos pegados a las costillas y quietos. Sube con el bíceps, baja en 2 segundos. Si el codo se va adelante o el cuerpo se balancea, es mucho peso. Mejor 5 kg limpios que 7,5 con impulso."},
{"n":"Curl martillo","g":"Bíceps","lv":"x","i":"Hammer_Curls","q":"curl martillo con mancuernas","c":"Codos quietos, palma mirando al muslo todo el recorrido. Alterna brazos si te cuesta mantener la postura."},
{"n":"Curl con barra","g":"Bíceps","lv":" ","i":"Barbell_Curl","q":"curl de biceps con barra","c":"Manos al ancho de los hombros, codos pegados al cuerpo. Sube sin echar la espalda atrás y baja hasta estirar el brazo. Con barra Z las muñecas sufren menos."},
{"n":"Curl en polea baja","g":"Bíceps","lv":" ","i":"Standing_Biceps_Cable_Curl","q":"curl de biceps en polea baja","c":"De frente a la polea baja, barra recta o Z. Codos fijos a los costados. La polea tira también abajo, así que baja despacio y sin dejar caer el peso."},
{"n":"Curl predicador (banco Scott)","g":"Bíceps","lv":" ","i":"Preacher_Curl","q":"curl predicador banco scott","c":"Axilas pegadas al borde del pad, brazos apoyados enteros. Baja casi hasta estirar sin bloquear el codo y sube sin despegar los brazos. Peso menor que el curl de pie."},
{"n":"Curl concentrado","g":"Bíceps","lv":" ","i":"Concentration_Curls","q":"curl concentrado con mancuerna","c":"Sentado, el codo apoyado en la cara interna del muslo. Sube la mancuerna hacia el hombro sin mover el codo y aprieta arriba. Un brazo a la vez, lento."},
{"n":"Curl inclinado (banco 45°)","g":"Bíceps","lv":" ","i":"Incline_Dumbbell_Curl","q":"curl inclinado con mancuernas","c":"Banco a 45°, brazos colgando detrás del cuerpo. Sube sin adelantar los codos. Estira mucho el bíceps, usa menos peso que de pie."},
{"n":"Pushdown (barra)","g":"Tríceps","lv":"x","i":"Triceps_Pushdown","q":"jalon de triceps en polea con barra","c":"Codos pegados a las costillas y quietos todo el recorrido. Baja hasta bloquear y aprieta un segundo. Sube solo hasta que el antebrazo pase la horizontal. Si los codos se abren o el cuerpo se inclina, sobra peso."},
{"n":"Pushdown (cuerda)","g":"Tríceps","lv":"/","i":"Triceps_Pushdown_-_Rope_Attachment","q":"jalon de triceps con cuerda","c":"Mismos cues que con barra, separando la cuerda al final. No te gusta: se usa si la barra está ocupada."},
{"n":"Extensión de tríceps sobre cabeza","g":"Tríceps","lv":"x","i":"Cable_Rope_Overhead_Triceps_Extension","q":"extension de triceps sobre la cabeza","nota":"La foto es en polea con cuerda. Con mancuerna es el mismo movimiento: codos fijos apuntando al techo.","c":"Codos apuntando al techo y cerca de las orejas. Baja la carga detrás de la cabeza hasta sentir el estiramiento, sube sin mover los codos. Es el que más estira el tríceps."},
{"n":"Fondos en banco","g":"Tríceps","lv":"x","i":"Bench_Dips","q":"fondos en banco para triceps","p":"peso corporal","c":"Manos al ancho de hombros, espalda pegada al banco. Baja hasta que el codo haga 90°, no más. Sube empujando con tríceps. Para hacerlo más duro, pies en otro banco y luego un disco en las piernas."},
{"n":"Press cerrado (barra)","g":"Tríceps","lv":"/","i":"Close-Grip_Barbell_Bench_Press","q":"press cerrado con barra triceps","c":"Manos al ancho de hombros, no más juntas. Codos pegados al cuerpo, la barra baja al pecho bajo. Primero pruébalo con barra vacía o en Smith."},
{"n":"Patada de tríceps (polea)","g":"Tríceps","lv":"x","i":"Tricep_Dumbbell_Kickback","q":"patada de triceps en polea","nota":"La foto es con mancuerna. En polea va igual: torso inclinado, codo alto y quieto, solo se mueve el antebrazo.","c":"Torso a 45°, codo alto y fijo a la altura de la espalda. Extiende hasta bloquear, pausa, baja. Peso ligero, es de contracción, no de carga."},
{"n":"Press francés (barra Z)","g":"Tríceps","lv":" ","i":"EZ-Bar_Skullcrusher","q":"press frances con barra z","c":"Acostado, brazos apuntando al techo y un poco hacia atrás. Dobla solo los codos y baja la barra hacia la frente, sin abrirlos. Sube estirando sin mover los hombros. Empieza liviano."},
{"n":"Leg press","g":"Cuádriceps","lv":"x","i":"Leg_Press","q":"prensa de piernas leg press","c":"Pies al ancho de hombros, al medio de la plataforma. Baja hasta que las rodillas hagan 90° sin que la espalda baja se despegue del asiento. Empuja con todo el pie. Nunca bloquees las rodillas arriba."},
{"n":"Extensión de cuádriceps","g":"Cuádriceps","lv":"x","i":"Leg_Extensions","q":"extension de cuadriceps en maquina","c":"Rodilla alineada con el eje de la máquina. Sube hasta estirar del todo, aprieta un segundo arriba, baja en 2 segundos. Sin impulso. Es de reps, 12 a 15."},
{"n":"Zancadas (mancuernas)","g":"Cuádriceps","lv":"x","i":"Dumbbell_Lunges","q":"zancadas con mancuernas","c":"Paso largo, torso recto, la rodilla de atrás baja casi al piso. La rodilla de adelante no pasa mucho la punta del pie. Sube empujando con el talón. Ligero, la coordinación va primero."},
{"n":"Sentadilla búlgara","g":"Cuádriceps","lv":"x","i":"Split_Squat_with_Dumbbells","q":"sentadilla bulgara con mancuernas","c":"Pie de atrás sobre el banco, el de adelante a un paso largo. Baja recto, la rodilla de adelante sigue la punta del pie. Es el más duro de todos por pierna. Empieza solo con el cuerpo."},
{"n":"Sentadilla goblet","g":"Cuádriceps","lv":"x","i":"Goblet_Squat","q":"sentadilla goblet","c":"Mancuerna pegada al pecho, codos abajo. Pies un poco más abiertos que los hombros, puntas hacia afuera. Baja entre las rodillas hasta que los codos toquen los muslos."},
{"n":"Sentadilla en Smith","g":"Cuádriceps","lv":"/","i":"Smith_Machine_Squat","q":"sentadilla en maquina smith","c":"Pies un paso adelante de la barra. La guía te sostiene, es el puente entre la goblet y la barra libre. Se prueba cuando la goblet pase de 20 kg."},
{"n":"Sentadilla con barra","g":"Cuádriceps","lv":"/","i":"Barbell_Squat","q":"sentadilla con barra tecnica","c":"Barra sobre el trapecio, pies al ancho de hombros. Baja con el pecho arriba hasta que el muslo quede paralelo al piso. Después del Smith, no antes."},
{"n":"Hack squat","g":"Cuádriceps","lv":" ","i":"Hack_Squat","q":"hack squat maquina tecnica","c":"Espalda pegada al respaldo, pies al medio de la plataforma. Baja hasta 90° sin que la cadera se despegue y sube sin bloquear las rodillas."},
{"n":"RDL con mancuernas","g":"Isquio y glúteo","lv":"x","i":"Stiff-Legged_Dumbbell_Deadlift","q":"peso muerto rumano con mancuernas","nota":"En la foto baja un poco más de lo necesario. Para cuando sientas el isquio estirado, con la espalda recta.","c":"Mancuernas pegadas a los muslos todo el recorrido. Rodillas apenas dobladas y fijas. La cadera va hacia atrás, no hacia abajo, la espalda queda recta como una tabla. Baja hasta sentir el isquio y sube apretando el glúteo."},
{"n":"Leg curl acostado","g":"Isquio y glúteo","lv":"x","i":"Lying_Leg_Curls","q":"curl femoral acostado en maquina","c":"Rodillas alineadas con el eje, rodillo justo sobre el talón. Cadera pegada al banco, sin levantarla al tirar. Sube en 1 segundo, baja en 2. Es de reps, 12 a 15."},
{"n":"Leg curl sentado","g":"Isquio y glúteo","lv":"x","i":"Seated_Leg_Curl","q":"curl femoral sentado en maquina","c":"Respaldo firme y muslos bajo el seguro. Rodilla alineada con el eje, sube en 1 segundo y baja en 2. Estira más el isquio que el acostado, altérnalos por semana."},
{"n":"Abducción de cadera (máquina)","g":"Isquio y glúteo","lv":"x","i":"Thigh_Abductor","q":"abduccion de cadera en maquina","c":"Espalda recta, abre hasta donde llegue sin que se despegue la cadera, pausa un segundo, cierra despacio. Peso medio, 15 reps. Glúteo medio y estabilidad de rodilla."},
{"n":"Peso muerto (barra)","g":"Isquio y glúteo","lv":" ","i":"Barbell_Deadlift","q":"peso muerto convencional tecnica","c":"Barra sobre la mitad del pie, espalda recta y pecho arriba antes de tirar. Empuja el piso con las piernas y la barra sube pegada al cuerpo. Aprende primero con poco peso y alguien que te vea."},
{"n":"RDL con barra","g":"Isquio y glúteo","lv":" ","i":"Romanian_Deadlift","q":"peso muerto rumano con barra","c":"Mismo gesto que con mancuernas, la barra pegada a los muslos. Cadera atrás, rodillas apenas dobladas, espalda recta. Va después de dominar el de mancuernas."},
{"n":"Hip thrust","g":"Isquio y glúteo","lv":" ","i":"Barbell_Hip_Thrust","q":"hip thrust con barra","c":"Espalda alta apoyada en el banco, barra sobre la cadera con almohadilla. Sube hasta que el cuerpo quede recto de rodillas a hombros y aprieta el glúteo arriba. No te gusta."},
{"n":"Buenos días","g":"Isquio y glúteo","lv":" ","i":"Good_Morning","q":"buenos dias con barra ejercicio","c":"Barra sobre el trapecio, rodillas suaves. Lleva la cadera atrás con la espalda recta hasta que el torso quede casi horizontal y sube. Muy liviano. No te gusta."},
{"n":"Elevación de talones de pie (máquina)","g":"Gemelo","lv":"x","i":"Standing_Calf_Raises","q":"elevacion de talones de pie en maquina","c":"Sube hasta la punta y pausa un segundo arriba. Baja hasta que el talón quede por debajo del escalón, sin rebotar abajo. Rango completo o no cuenta. 15 reps."},
{"n":"Elevación de talones en leg press","g":"Gemelo","lv":"x","i":"Calf_Press_On_The_Leg_Press_Machine","q":"pantorrillas en prensa de piernas","c":"Solo la punta del pie en el borde de la plataforma, rodillas casi rectas y fijas. Sube a la punta, pausa, y baja hasta estirar. Al final del leg press con el mismo peso o menos."},
{"n":"Elevación de talones sentado","g":"Gemelo","lv":" ","i":"Seated_Calf_Raise","q":"elevacion de talones sentado maquina","c":"Rodillas a 90° bajo el pad, punta del pie en el borde. Sube hasta la punta, pausa y baja hasta estirar. Trabaja el sóleo, la parte baja del gemelo."},
{"n":"Plancha","g":"Core","lv":"x","i":"Plank","q":"plancha abdominal tecnica","uno":1,"p":"peso corporal","c":"Codos bajo los hombros, cuerpo en línea recta, glúteo apretado. Si la cadera se cae o sube, se acabó la serie. Empieza en 30 segundos y sube de a 10."},
{"n":"Elevación de piernas en banco","g":"Core","lv":"x","i":"Flat_Bench_Lying_Leg_Raise","q":"elevacion de piernas acostado en banco","p":"peso corporal","c":"Manos bajo el glúteo, espalda baja pegada al banco. Sube las piernas hasta 90° y baja despacio sin tocar el piso."},
{"n":"Elevación de piernas colgado","g":"Core","lv":"x","i":"Hanging_Leg_Raise","q":"elevacion de piernas colgado en barra","p":"peso corporal","c":"Colgado de la barra, sin balancearte. Sube las piernas rectas o con las rodillas dobladas hasta 90° y baja despacio. Si te balanceas, para y empieza quieto."},
{"n":"Crunch en polea (cuerda)","g":"Core","lv":" ","i":"Cable_Crunch","q":"crunch en polea con cuerda","c":"De rodillas frente a la polea alta, cuerda junto a la cabeza. Enrolla el torso llevando los codos a los muslos, sin sentarte sobre los talones. La cadera queda quieta."},
{"n":"Rueda abdominal","g":"Core","lv":" ","i":"Ab_Roller","q":"rueda abdominal principiantes","p":"peso corporal","c":"De rodillas, brazos rectos. Rueda hacia adelante hasta donde puedas sin que la espalda baja se hunda y vuelve con el abdomen. Empieza con recorridos cortos."},
{"n":"Crunch en máquina","g":"Core","lv":" ","i":"Ab_Crunch_Machine","q":"crunch en maquina abdominal","c":"Ajusta el asiento y el pecho al pad. Enrolla el torso hacia las rodillas apretando el abdomen, sin tirar con los brazos. Vuelve despacio."},
{"n":"Russian twist","g":"Core","lv":" ","i":"Russian_Twist","q":"russian twist abdominales","p":"peso corporal","c":"Sentado, torso inclinado atrás y pies en el piso o levantados. Gira el torso de lado a lado llevando las manos o un disco junto a la cadera. Gira los hombros, no solo los brazos."},
{"n":"Dominadas supinas (chin-up)","g":"Espalda","lv":" ","i":"Chin-Up","q":"dominadas supinas chin up tecnica","c":"Agarra la barra con las palmas hacia ti y manos más juntas que los hombros. Sube hasta pasar la barbilla, llevando los codos hacia abajo y las costillas. Baja controlado hasta extender del todo y evita balancearte.","cat":1},
{"n":"Jalón agarre en V (polea)","g":"Espalda","lv":" ","i":"V-Bar_Pulldown","q":"jalon agarre en v polea tecnica","c":"Siéntate con los muslos fijos bajo el rodillo y el pecho afuera, inclinado unos 30 grados. Tira del agarre hasta la parte alta del pecho llevando los codos atrás. No te balancees ni encojas los hombros.","cat":1},
{"n":"Jalón supino (polea)","g":"Espalda","lv":" ","i":"Underhand_Cable_Pulldowns","q":"jalon supino polea agarre cerrado tecnica","c":"Agarra la barra con las palmas hacia ti y manos más juntas que los hombros. Con el pecho arriba, tira hasta la parte alta del pecho y siente el bíceps y el dorsal. Sube controlando, sin soltar el peso de golpe.","cat":1},
{"n":"Jalón a una mano (polea)","g":"Espalda","lv":" ","i":"One_Arm_Lat_Pulldown","q":"jalon a una mano polea dorsal tecnica","c":"Fija bien las piernas bajo el rodillo y agarra la manija con la palma hacia abajo. Tira bajando el codo pegado al costado hasta sentir el dorsal. Pausa abajo y sube lento sin rotar el torso.","cat":1},
{"n":"Remo sentado en polea","g":"Espalda","lv":" ","i":"Seated_Cable_Rows","q":"remo sentado en polea tecnica","c":"Siéntate con las rodillas ligeramente flexionadas y la espalda neutra, pecho arriba. Tira del agarre hacia el abdomen juntando los omóplatos y pausa un segundo. Regresa estirando los brazos sin encorvarte ni balancear el torso.","cat":1},
{"n":"Remo sentado a una mano (polea)","g":"Espalda","lv":" ","i":"Seated_One-arm_Cable_Pulley_Rows","q":"remo a una mano en polea sentado tecnica","c":"Siéntate con los pies en la plataforma y la espalda recta. Tira de la manija hacia el costado del abdomen manteniendo el codo cerca del cuerpo. Aprieta la espalda al final y evita girar el torso para ayudarte.","cat":1},
{"n":"Remo alto en máquina","g":"Espalda","lv":" ","i":"Leverage_High_Row","q":"remo alto en maquina tecnica espalda","c":"Ajusta el asiento para alcanzar las manijas altas y fija las piernas bajo el rodillo. Tira hacia el torso juntando los omóplatos, con el pecho arriba. Pausa y regresa lento, sin soltar el peso ni encoger los hombros.","cat":1},
{"n":"Remo invertido (barra)","g":"Espalda","lv":" ","i":"Inverted_Row","q":"remo invertido barra tecnica","c":"Cuélgate bajo una barra a altura de cintura con el cuerpo recto y los talones apoyados. Lleva el pecho hacia la barra juntando los omóplatos. Mantén glúteos apretados y no dejes que la cadera caiga.","cat":1},
{"n":"Remo en banco inclinado (mancuernas)","g":"Espalda","lv":" ","i":"Dumbbell_Incline_Row","q":"remo banco inclinado mancuernas pecho apoyado tecnica","c":"Apoya el pecho en el banco inclinado con una mancuerna en cada mano y brazos extendidos. Lleva los codos hacia atrás juntando los omóplatos y pausa arriba. Baja controlado sin despegar el pecho del banco.","cat":1},
{"n":"Remo inclinado con mancuernas","g":"Espalda","lv":" ","i":"Bent_Over_Two-Dumbbell_Row","q":"remo con mancuernas inclinado tecnica","c":"Flexiona un poco las rodillas e inclina el torso casi paralelo al suelo con la espalda recta y la cabeza arriba. Sube las mancuernas hacia las costillas con los codos pegados. Baja lento y no uses impulso.","cat":1},
{"n":"Remo en barra T","g":"Espalda","lv":" ","i":"T-Bar_Row_with_Handle","q":"remo en barra t tecnica","c":"Párate sobre la barra con la cadera atrás, el pecho arriba y la espalda neutra. Tira del peso hacia la parte alta del abdomen juntando los omóplatos. Baja controlado y evita subir el torso para ayudarte.","cat":1},
{"n":"Remo inclinado (Smith)","g":"Espalda","lv":" ","i":"Smith_Machine_Bent_Over_Row","q":"remo en maquina smith inclinado tecnica","c":"Inclina el torso casi paralelo al suelo con las rodillas algo flexionadas y la espalda recta. Tira de la barra hacia el abdomen bajo con los codos pegados. Baja lento y no levantes el torso con cada repetición.","cat":1},
{"n":"Encogimientos con barra","g":"Espalda","lv":" ","i":"Barbell_Shrug","q":"encogimientos de hombros con barra trapecio tecnica","c":"De pie, con la barra al frente y las manos algo más anchas que los hombros. Sube los hombros directo hacia las orejas y pausa un segundo. Baja controlado y no rotes los hombros ni flexiones los codos.","cat":1},
{"n":"Encogimientos en polea","g":"Espalda","lv":" ","i":"Cable_Shrugs","q":"encogimientos en polea trapecio tecnica","c":"Párate cerca de la polea baja con la barra al frente y los brazos extendidos. Sube los hombros lo más alto posible y mantén un segundo arriba. Baja lento, con los codos rectos y sin jalar con los brazos.","cat":1},
{"n":"Peso muerto desde rack","g":"Espalda","lv":" ","i":"Rack_Pulls","q":"peso muerto desde rack rack pull tecnica","c":"Coloca la barra en los pines cerca de la rodilla, con pies bajo la cadera y espalda arqueada. Sube extendiendo cadera y rodillas a la vez, con la barra pegada al cuerpo. No hiperextiendas la espalda al terminar.","cat":1},
{"n":"Pullover en polea con cuerda","g":"Espalda","lv":" ","i":"Rope_Straight-Arm_Pulldown","q":"pullover en polea alta con cuerda brazos rectos tecnica","c":"Con la cuerda en polea alta, inclínate desde la cadera y mantén los brazos casi rectos. Baja la cuerda hasta los muslos usando el dorsal, no los codos. Pausa abajo y sube lento hasta sentir el estiramiento.","cat":1},
{"n":"Aperturas con mancuernas","g":"Pecho","lv":" ","i":"Dumbbell_Flyes","q":"aperturas con mancuernas pecho tecnica","c":"Acostado en banco plano, mancuernas arriba con palmas enfrentadas y codos ligeramente flexionados. Abre los brazos en arco hasta sentir el estiramiento del pecho. Cierra juntando arriba y no bajes tanto que se cargue el hombro.","cat":1},
{"n":"Aperturas inclinadas con mancuernas","g":"Pecho","lv":" ","i":"Incline_Dumbbell_Flyes","q":"aperturas inclinadas con mancuernas tecnica","c":"Usa un banco con inclinación suave, de 30 grados o menos. Baja las mancuernas abiertas en arco con los codos algo flexionados y sube apretando el pecho alto. Evita convertirlo en press ni bajar demasiado.","cat":1},
{"n":"Cruce de poleas bajo","g":"Pecho","lv":" ","i":"Low_Cable_Crossover","q":"cruce de poleas bajo pecho superior tecnica","c":"Con las poleas abajo, da un paso adelante y mantén los codos ligeramente flexionados. Sube las manos hacia la línea media del pecho, juntándolas arriba. Regresa lento sin balancear el torso ni doblar los codos más.","cat":1},
{"n":"Aperturas inclinadas en polea","g":"Pecho","lv":" ","i":"Incline_Cable_Flye","q":"aperturas inclinadas en polea tecnica","c":"Coloca el banco a 45 grados entre las poleas bajas y agarra una manija en cada mano. Abre los brazos en arco con codos semiflexionados y vuelve juntando frente a la cara. Mantén los hombros atrás.","cat":1},
{"n":"Aperturas planas en polea","g":"Pecho","lv":" ","i":"Flat_Bench_Cable_Flyes","q":"aperturas planas en polea banco tecnica","c":"Acostado en banco plano entre poleas bajas, brazos abiertos con los codos ligeramente flexionados. Junta las manos sobre el pecho en arco, manteniendo siempre la misma flexión de codo. Baja lento y sin rebotar.","cat":1},
{"n":"Press declinado con barra","g":"Pecho","lv":" ","i":"Decline_Barbell_Bench_Press","q":"press declinado con barra tecnica","c":"Asegura las piernas en el banco declinado y baja la barra hasta la parte baja del pecho con agarre medio. Empuja arriba sin bloquear fuerte los codos. Mantén las muñecas rectas y pide ayuda con cargas altas.","cat":1},
{"n":"Press declinado con mancuernas","g":"Pecho","lv":" ","i":"Decline_Dumbbell_Bench_Press","q":"press declinado con mancuernas tecnica","c":"Asegura las piernas y lleva las mancuernas a la altura del pecho con las palmas al frente. Baja lento hasta sentir el estiramiento y empuja arriba juntándolas. Controla el peso y evita abrir demasiado los codos.","cat":1},
{"n":"Press de banca (Smith)","g":"Pecho","lv":" ","i":"Smith_Machine_Bench_Press","q":"press de banca en maquina smith tecnica","c":"Alinea el banco bajo la barra, con agarre más ancho que los hombros y los omóplatos retraídos. Baja la barra a la mitad del pecho y empuja arriba. Mantén los pies firmes y no despegues la espalda del banco.","cat":1},
{"n":"Press inclinado (Smith)","g":"Pecho","lv":" ","i":"Smith_Machine_Incline_Bench_Press","q":"press inclinado en maquina smith tecnica","c":"Alinea la parte alta del pecho con la barra y agarra algo más ancho que los hombros. Baja controlado hasta rozar el pecho y empuja arriba sin bloquear los codos. Mantén los omóplatos juntos y los glúteos en el banco.","cat":1},
{"n":"Press inclinado en máquina","g":"Pecho","lv":" ","i":"Leverage_Incline_Chest_Press","q":"press inclinado en maquina pecho tecnica","c":"Ajusta el asiento para que las manijas queden a la altura de la parte alta del pecho. Con el pecho arriba y los omóplatos juntos, empuja hacia adelante y regresa sin soltar la tensión. Evita encoger los hombros.","cat":1},
{"n":"Press inclinado agarre neutro (mancuernas)","g":"Pecho","lv":" ","i":"Hammer_Grip_Incline_DB_Bench_Press","q":"press inclinado mancuernas agarre neutro martillo tecnica","c":"En banco inclinado, sostén las mancuernas con las palmas enfrentadas a la altura de los hombros. Empuja arriba sin chocarlas y baja lento hasta sentir el estiramiento. Mantén los codos a unos 45 grados del torso.","cat":1},
{"n":"Pullover con mancuerna","g":"Pecho","lv":" ","i":"Straight-Arm_Dumbbell_Pullover","q":"pullover con mancuerna pecho tecnica","c":"Apoya solo los hombros en el banco, con la cadera baja y los pies firmes. Sostén la mancuerna sobre el pecho y bájala detrás de la cabeza con los codos casi rectos. Regresa usando el pecho, sin arquear de más la espalda.","cat":1},
{"n":"Flexiones con pies elevados","g":"Pecho","lv":" ","i":"Push-Ups_With_Feet_Elevated","q":"flexiones con pies elevados pecho superior tecnica","c":"Pon los pies sobre un banco y las manos algo más abiertas que los hombros. Baja el pecho casi al suelo con el cuerpo en línea recta y empuja arriba. Aprieta abdomen y glúteos para que la cadera no caiga.","cat":1},
{"n":"Press de banca agarre ancho","g":"Pecho","lv":" ","i":"Wide-Grip_Barbell_Bench_Press","q":"press de banca agarre ancho tecnica","c":"Acostado, agarra la barra unos 7 cm más ancho que los hombros y retrae los omóplatos. Baja hasta el pecho medio con control y empuja arriba. Mantén los pies firmes y no rebotes la barra en el pecho.","cat":1},
{"n":"Press de pecho en polea","g":"Pecho","lv":" ","i":"Cable_Chest_Press","q":"press de pecho en polea tecnica","c":"Sentado con el pecho arriba y los codos a unos 45 grados del cuerpo. Empuja las manijas al frente juntándolas sin despegar los omóplatos del respaldo. Regresa lento hasta sentir el estiramiento del pecho.","cat":1},
{"n":"Press Arnold","g":"Hombro","lv":" ","i":"Arnold_Dumbbell_Press","q":"press arnold tecnica hombro","c":"Sentado con respaldo, parte con las mancuernas frente al pecho y las palmas hacia ti. Al subir, gira las muñecas hasta que las palmas miren al frente. Baja girando de vuelta y evita arquear la espalda.","cat":1},
{"n":"Press de hombro con mancuernas","g":"Hombro","lv":" ","i":"Dumbbell_Shoulder_Press","q":"press de hombro con mancuernas sentado tecnica","c":"Sentado con respaldo, mancuernas a la altura de las orejas y palmas al frente. Empuja arriba sin chocarlas y baja controlado hasta los hombros. Mantén el abdomen firme y no arquees la zona lumbar.","cat":1},
{"n":"Press militar (Smith)","g":"Hombro","lv":" ","i":"Smith_Machine_Overhead_Shoulder_Press","q":"press militar en maquina smith tecnica","c":"Sentado con respaldo y la barra alineada con tu nariz. Baja hasta la barbilla y empuja arriba extendiendo los brazos sin bloquear fuerte los codos. Mantén los pies firmes y no eches la cabeza hacia atrás.","cat":1},
{"n":"Press de hombro en máquina","g":"Hombro","lv":" ","i":"Machine_Shoulder_Military_Press","q":"press de hombro en maquina tecnica","c":"Ajusta el asiento para que las manijas queden a la altura de los hombros, con la espalda apoyada. Empuja hasta extender los brazos y pausa un segundo arriba. Baja lento y no despegues la espalda del respaldo.","cat":1},
{"n":"Aperturas inversas con mancuernas","g":"Hombro","lv":" ","i":"Reverse_Flyes","q":"aperturas inversas con mancuernas banco inclinado deltoides posterior","c":"Apoya el pecho en un banco inclinado con las mancuernas colgando y palmas enfrentadas. Abre los brazos hacia los lados con los codos ligeramente flexionados, apretando atrás. Baja lento y no uses impulso.","cat":1},
{"n":"Aperturas inversas en polea","g":"Hombro","lv":" ","i":"Cable_Rear_Delt_Fly","q":"aperturas inversas en polea cruzada deltoides posterior tecnica","c":"Con poleas altas, cruza los cables y agarra cada manija con la mano contraria. Abre los brazos hacia atrás y afuera manteniéndolos casi rectos. Pausa al final y regresa lento sin encoger los hombros.","cat":1},
{"n":"Remo al mentón con barra","g":"Hombro","lv":" ","i":"Upright_Barbell_Row","q":"remo al menton con barra tecnica","c":"Agarra la barra con las manos un poco más cerradas que los hombros. Sube llevando los codos arriba y a los lados, con la barra pegada al cuerpo, hasta el pecho. No pases de ahí si molesta el hombro.","cat":1},
{"n":"Remo al mentón con mancuernas","g":"Hombro","lv":" ","i":"Standing_Dumbbell_Upright_Row","q":"remo al menton con mancuernas tecnica","c":"De pie, con las mancuernas frente a los muslos y los codos ligeramente flexionados. Sube liderando con los codos hasta la altura del pecho y baja controlado. Mantén el torso recto y evita balancearte.","cat":1},
{"n":"Elevación frontal en polea","g":"Hombro","lv":" ","i":"Front_Cable_Raise","q":"elevacion frontal en polea tecnica","c":"Dale la espalda a la polea baja con la manija frente a los muslos. Sube el brazo casi recto hasta la altura del hombro y baja lento. Mantén el torso quieto, sin balancearte, y no pases de la línea del hombro.","cat":1},
{"n":"Elevación frontal con disco","g":"Hombro","lv":" ","i":"Front_Plate_Raise","q":"elevacion frontal con disco hombro tecnica","c":"De pie, sostén el disco con ambas manos y los codos ligeramente flexionados. Sube el disco al frente hasta la altura de los ojos y baja lento. Mantén el torso firme y no te ayudes con la cadera.","cat":1},
{"n":"Pájaros sentado (mancuernas)","g":"Hombro","lv":" ","i":"Seated_Bent-Over_Rear_Delt_Raise","q":"pajaros sentado mancuernas deltoides posterior tecnica","c":"Sentado en el borde del banco, inclina el torso sobre los muslos con las mancuernas bajo las pantorrillas. Abre los brazos hacia los lados con codos semiflexionados, apretando atrás. Baja lento sin levantar el torso.","cat":1},
{"n":"Rotación externa en polea","g":"Hombro","lv":" ","i":"External_Rotation_with_Cable","q":"rotacion externa hombro en polea manguito rotador tecnica","c":"Con la polea a la altura del codo, pega el codo al costado doblado a 90 grados. Rota el antebrazo hacia afuera sin separar el codo y vuelve lento. Usa poco peso y mueve solo el hombro, no el torso.","cat":1},
{"n":"Press de hombro en polea","g":"Hombro","lv":" ","i":"Cable_Shoulder_Press","q":"press de hombro en polea de pie tecnica","c":"De pie entre las poleas bajas, con las manijas a la altura de los hombros y palmas al frente. Empuja arriba hasta extender los brazos y baja controlado. Mantén pecho arriba y abdomen firme sin arquear la espalda.","cat":1},
{"n":"Elevaciones laterales sentado","g":"Hombro","lv":" ","i":"Seated_Side_Lateral_Raise","q":"elevaciones laterales sentado mancuernas tecnica","c":"Sentado con las mancuernas a los lados y el torso quieto. Sube los brazos hacia afuera con los codos ligeramente flexionados, como si vertieras agua, hasta la altura del hombro. Baja lento sin balancear.","cat":1},
{"n":"Elevación lateral a una mano","g":"Hombro","lv":" ","i":"One-Arm_Side_Laterals","q":"elevacion lateral a una mano mancuerna tecnica","c":"Sujétate de algo firme e inclínate un poco hacia ese lado. Sube la mancuerna hacia afuera con el codo ligeramente flexionado hasta la altura del hombro. Baja lento y evita usar impulso del torso.","cat":1},
{"n":"Curl martillo en polea (cuerda)","g":"Bíceps","lv":" ","i":"Cable_Hammer_Curls_-_Rope_Attachment","q":"curl martillo polea baja cuerda tecnica","c":"Con la cuerda en polea baja y agarre neutro, pega los codos a las costillas. Sube solo con los antebrazos hasta que las manos lleguen a los hombros y baja lento. No te balancees con el torso para ayudarte.","cat":1},
{"n":"Curl predicador en máquina","g":"Bíceps","lv":" ","i":"Machine_Preacher_Curls","q":"curl predicador maquina como se hace","c":"Ajusta el asiento para que la parte trasera de los brazos descanse completa en el cojín. Sube las asas con agarre supino y aprieta arriba un segundo. Baja controlado sin despegar los codos ni soltar el peso abajo.","cat":1},
{"n":"Curl araña","g":"Bíceps","lv":" ","i":"Spider_Curl","q":"curl arana barra z banco inclinado como se hace","c":"Apoya el pecho y el abdomen en el respaldo inclinado del banco con los brazos colgando hacia abajo. Sube la barra Z sin mover los codos y baja hasta casi extender. Evita levantar el pecho del banco para tomar impulso.","cat":1},
{"n":"Curl inverso con barra","g":"Bíceps","lv":" ","i":"Reverse_Barbell_Curl","q":"curl inverso con barra agarre prono antebrazo tecnica","c":"Sujeta la barra con agarre prono, a la anchura de los hombros y los codos pegados al torso. Sube solo con los antebrazos hasta contraer y baja lento. Mantén las muñecas rectas y no balancees la espalda.","cat":1},
{"n":"Curl Zottman","g":"Bíceps","lv":" ","i":"Zottman_Curl","q":"curl zottman como se hace","c":"Sube las mancuernas con agarre supino, como un curl normal. Arriba gira las muñecas para quedar con las palmas hacia abajo y baja lento en esa posición. Rota otra vez abajo. No muevas los codos ni uses impulso.","cat":1},
{"n":"Curl en polea alta (doble)","g":"Bíceps","lv":" ","i":"High_Cable_Curls","q":"curl polea alta doble biceps tecnica","c":"Colócate entre dos poleas altas con los brazos extendidos a los lados, a la altura de los hombros. Dobla los codos llevando las manos hacia las orejas y regresa lento. Los codos quedan fijos y a la altura del hombro, sin caer.","cat":1},
{"n":"Curl alterno con mancuernas","g":"Bíceps","lv":" ","i":"Dumbbell_Alternate_Bicep_Curl","q":"curl alterno mancuernas biceps como se hace","c":"De pie con los codos pegados al torso, sube una mancuerna girando la palma hacia arriba durante el recorrido. Baja lento y repite con el otro brazo. No balancees el cuerpo ni dejes que los codos se adelanten.","cat":1},
{"n":"Curl martillo cruzado (mancuernas)","g":"Bíceps","lv":" ","i":"Cross_Body_Hammer_Curl","q":"curl martillo cruzado mancuernas como se hace","c":"Con las palmas mirándose, sube la mancuerna en diagonal hacia el hombro contrario sin girar la muñeca. Aprieta un segundo arriba y baja por el mismo camino. Mantén el codo fijo al costado y el torso quieto.","cat":1},
{"n":"Curl arrastrado con barra","g":"Bíceps","lv":" ","i":"Drag_Curl","q":"curl arrastrado barra drag curl tecnica","c":"Con agarre supino, sube la barra pegada al cuerpo llevando los codos hacia atrás, como si la arrastraras por el abdomen y el pecho. Baja igual de pegada. No eleves los hombros ni te inclines hacia atrás.","cat":1},
{"n":"Curl de bíceps en máquina","g":"Bíceps","lv":" ","i":"Machine_Bicep_Curl","q":"curl biceps en maquina como se hace","c":"Regula el asiento para que los brazos descansen sobre el cojín con los codos alineados al eje de la máquina. Sube las asas, pausa arriba y baja lento. No dejes caer la pila al final para mantener tensión continua.","cat":1},
{"n":"Fondos en paralelas (tríceps)","g":"Tríceps","lv":" ","i":"Dips_-_Triceps_Version","q":"fondos en paralelas triceps tecnica","c":"Sostente con los brazos casi extendidos, el torso vertical y los codos cerca del cuerpo. Baja hasta que el codo forme unos 90 grados y empuja hacia arriba. Si te inclinas hacia delante, el trabajo se va al pecho.","cat":1},
{"n":"Jalón de tríceps agarre supino (polea)","g":"Tríceps","lv":" ","i":"Reverse_Grip_Triceps_Pushdown","q":"jalon triceps agarre supino polea tecnica","c":"Con la barra en polea alta y agarre supino, pega los codos al cuerpo y extiende los brazos hacia abajo hasta bloquear. Sube hasta el pecho sin separar los codos. Evita encorvarte o usar el peso del cuerpo para empujar.","cat":1},
{"n":"Jalón de tríceps (barra V)","g":"Tríceps","lv":" ","i":"Triceps_Pushdown_-_V-Bar_Attachment","q":"jalon triceps polea barra v tecnica","c":"Agarra la barra V con las palmas hacia abajo y los codos pegados al torso. Extiende los codos hasta bajar la barra a los muslos y sube hasta que el antebrazo quede casi horizontal. Solo se mueven los antebrazos.","cat":1},
{"n":"Extensión de tríceps sobre la cabeza (mancuerna)","g":"Tríceps","lv":" ","i":"Standing_Dumbbell_Triceps_Extension","q":"extension triceps tras nuca mancuerna de pie tecnica","c":"Sostén una mancuerna con ambas manos sobre la cabeza y baja detrás de la nuca doblando solo los codos. Extiende de nuevo hasta arriba. Mantén los codos apuntando al frente y las costillas cerradas, sin arquear la espalda.","cat":1},
{"n":"Press francés con mancuernas","g":"Tríceps","lv":" ","i":"Lying_Dumbbell_Tricep_Extension","q":"press frances mancuernas triceps tumbado tecnica","c":"Acostado en el banco, con las mancuernas sobre el pecho y las palmas enfrentadas, baja hasta los lados de la cabeza doblando solo los codos. Extiende otra vez. Evita abrir los codos o dejar que se vayan hacia atrás.","cat":1},
{"n":"Extensión de tríceps en máquina","g":"Tríceps","lv":" ","i":"Machine_Triceps_Extension","q":"extension de triceps en maquina como se hace","c":"Ajusta el asiento para que los brazos descansen sobre el cojín. Extiende los codos hasta casi bloquear, pausa y regresa lento. No dejes que la pila golpee abajo ni levantes los hombros hacia las orejas.","cat":1},
{"n":"Fondos en máquina (asistida o sentado)","g":"Tríceps","lv":" ","i":"Dip_Machine","q":"maquina de fondos triceps sentado como se usa","c":"Siéntate con la espalda apoyada y agarra las asas con los codos pegados a los costados. Empuja hacia abajo hasta extender los brazos sin bloquearlos del todo y regresa lento. No separes los codos ni despegues la espalda.","cat":1},
{"n":"Extensión de tríceps a una mano (polea)","g":"Tríceps","lv":" ","i":"Cable_One_Arm_Tricep_Extension","q":"extension triceps una mano polea agarre supino tecnica","c":"Con la polea alta y agarre supino, pega el codo al costado y extiende el brazo hacia abajo hasta bloquear. Regresa lento hasta un ángulo agudo. Mantén el hombro quieto y el torso firme, sin girar.","cat":1},
{"n":"Flexiones cerradas (tríceps)","g":"Tríceps","lv":" ","i":"Push-Ups_-_Close_Triceps_Position","q":"flexiones cerradas triceps tecnica","c":"Coloca las manos más juntas que los hombros y baja el pecho hasta casi tocar el suelo con el cuerpo recto. Empuja hasta extender los brazos. Mantén los codos cerca de las costillas y no dejes caer la cadera.","cat":1},
{"n":"Press cerrado con mancuerna","g":"Tríceps","lv":" ","i":"Close-Grip_Dumbbell_Press","q":"press cerrado con mancuerna triceps tecnica","c":"Acostado, sostén una mancuerna vertical sobre el pecho con las palmas contra el disco superior. Baja doblando los codos pegados al cuerpo y empuja hasta extender. No abras los codos como en un press de pecho.","cat":1},
{"n":"Press de tríceps sentado (mancuerna)","g":"Tríceps","lv":" ","i":"Seated_Triceps_Press","q":"press de triceps sentado mancuerna tecnica","c":"Sentado con respaldo, sostén una mancuerna sobre la cabeza con ambas manos. Baja detrás de la cabeza doblando los codos, que se quedan cerca de las orejas, y extiende. No arquees la espalda ni abras los codos.","cat":1},
{"n":"Press francés en polea (tumbado)","g":"Tríceps","lv":" ","i":"Cable_Lying_Triceps_Extension","q":"press frances polea baja tumbado triceps tecnica","c":"Tumbado en el banco con la barra de polea baja sobre el pecho, baja hacia la frente doblando solo los codos y extiende de nuevo. Los brazos superiores se mantienen fijos. Evita que los codos se abran o se muevan.","cat":1},
{"n":"Sentadilla con mancuernas","g":"Cuádriceps","lv":" ","i":"Dumbbell_Squat","q":"sentadilla con mancuernas tecnica","c":"De pie con una mancuerna en cada mano y los pies al ancho de los hombros, baja sentándote hacia atrás hasta que los muslos queden paralelos. Sube empujando con todo el pie. Mantén el pecho arriba y la espalda recta.","cat":1},
{"n":"Subidas al cajón con mancuernas","g":"Cuádriceps","lv":" ","i":"Dumbbell_Step_Ups","q":"subidas al cajon con mancuernas step up tecnica","c":"Con una mancuerna en cada mano, apoya un pie completo en el cajón y sube empujando con el talón de esa pierna. Baja controlado, sin dejarte caer. Evita impulsarte con la pierna de atrás o inclinarte hacia delante.","cat":1},
{"n":"Zancada hacia atrás (mancuernas)","g":"Cuádriceps","lv":" ","i":"Dumbbell_Rear_Lunge","q":"zancada hacia atras mancuernas tecnica","c":"Da un paso largo atrás y baja hasta que la rodilla trasera casi roce el piso. La espinilla de adelante queda vertical y el torso erguido. Sube empujando con la pierna delantera. Evita que la rodilla se desplace hacia dentro.","cat":1},
{"n":"Zancadas caminando (peso corporal)","g":"Cuádriceps","lv":" ","i":"Bodyweight_Walking_Lunge","q":"zancadas caminando peso corporal tecnica","c":"Da un paso largo al frente y baja hasta que la rodilla trasera casi toque el suelo. Empuja con el talón delantero y avanza con la otra pierna. Mantén el torso erguido y la rodilla alineada con el pie.","cat":1},
{"n":"Zancadas caminando (barra)","g":"Cuádriceps","lv":" ","i":"Barbell_Walking_Lunge","q":"zancadas caminando con barra tecnica","c":"Con la barra sobre la parte alta de la espalda, da un paso largo y baja hasta que la rodilla trasera casi toque el suelo. Empuja con el talón delantero y avanza. Mantén el torso erguido y la mirada al frente.","cat":1},
{"n":"Sentadilla frontal con barra","g":"Cuádriceps","lv":" ","i":"Front_Squat_Clean_Grip","q":"sentadilla frontal con barra tecnica codos altos","c":"Apoya la barra sobre los hombros con los codos altos y baja manteniendo el torso muy vertical, hasta paralelo o más. Sube empujando con todo el pie. Si los codos caen, la barra rueda y la espalda se encorva.","cat":1},
{"n":"Prensa con pies juntos","g":"Cuádriceps","lv":" ","i":"Narrow_Stance_Leg_Press","q":"prensa de piernas pies juntos cuadriceps tecnica","c":"Pon los pies juntos y al centro de la plataforma, con las puntas ligeramente abiertas. Baja hasta unos 90 grados de rodilla y empuja sin bloquearlas al final. No levantes la cadera del asiento ni dejes caer el peso.","cat":1},
{"n":"Extensión de cuádriceps a una pierna","g":"Cuádriceps","lv":" ","i":"Single-Leg_Leg_Extension","q":"extension de cuadriceps una pierna maquina tecnica","c":"Ajusta la máquina para que el eje quede a la altura de la rodilla y el cojín sobre la parte baja de la espinilla. Extiende una pierna hasta arriba, pausa y baja lento. No uses impulso ni levantes la cadera del asiento.","cat":1},
{"n":"Sentadilla al cajón","g":"Cuádriceps","lv":" ","i":"Box_Squat","q":"sentadilla al cajon box squat tecnica","c":"Con la barra en la espalda, siéntate hacia atrás hasta tocar el cajón con la espinilla vertical. Pausa sin relajarte del todo y sube empujando con los pies. No te dejes caer ni redondees la espalda al apoyar.","cat":1},
{"n":"Sentadilla libre (peso corporal)","g":"Cuádriceps","lv":" ","i":"Bodyweight_Squat","q":"sentadilla peso corporal tecnica correcta","c":"Pies al ancho de los hombros, siéntate hacia atrás doblando cadera y rodillas hasta donde llegues con control. Sube rápido empujando con el pie completo. Mantén el pecho arriba y las rodillas abriéndose hacia fuera, no hacia dentro.","cat":1},
{"n":"Sentadilla sumo con mancuerna","g":"Cuádriceps","lv":" ","i":"Plie_Dumbbell_Squat","q":"sentadilla sumo con mancuerna tecnica","c":"Pies más anchos que los hombros y puntas hacia fuera, con una mancuerna colgando entre las piernas. Baja recto hasta que los muslos queden paralelos y sube apretando los glúteos. Las rodillas siguen la dirección de los pies.","cat":1},
{"n":"Prensa en Smith (tumbado)","g":"Cuádriceps","lv":" ","i":"Smith_Machine_Leg_Press","q":"prensa en maquina smith tumbado como se hace","c":"Acostado bajo la barra del Smith con los pies al centro, empuja subiendo hasta casi extender las piernas sin bloquear las rodillas. Baja lento. Asegúrate de que los seguros estén bien puestos y no despegues la espalda baja.","cat":1},
{"n":"Zancada con barra","g":"Cuádriceps","lv":" ","i":"Barbell_Lunge","q":"zancada con barra tecnica","c":"Con la barra sobre la parte alta de la espalda, da un paso largo al frente y baja hasta que la rodilla trasera casi toque el suelo. Empuja con el talón para volver. Mantén el torso erguido y la rodilla sobre el pie.","cat":1},
{"n":"Máquina de aductores","g":"Isquio y glúteo","lv":" ","i":"Thigh_Adductor","q":"maquina de aductores como se usa","c":"Siéntate con la espalda apoyada y las piernas abiertas sobre las almohadillas. Junta las piernas con control, aprieta un segundo y vuelve lento. No uses impulso ni abras más de lo que tu cadera permite con comodidad.","cat":1},
{"n":"Puente de glúteo con barra","g":"Isquio y glúteo","lv":" ","i":"Barbell_Glute_Bridge","q":"puente de gluteo con barra tecnica","c":"Con la espalda alta apoyada en el suelo y la barra sobre la cadera (usa una almohadilla), empuja con los talones hasta extender la cadera. Aprieta los glúteos arriba y baja lento. No arquees la zona lumbar al subir.","cat":1},
{"n":"Puente de glúteo a una pierna","g":"Isquio y glúteo","lv":" ","i":"Single_Leg_Glute_Bridge","q":"puente de gluteo a una pierna tecnica","c":"Acostado con un pie apoyado y la otra rodilla al pecho, empuja con el talón y eleva la cadera lo más alto posible. Pausa arriba y baja con control. Mantén la cadera nivelada y sin girar hacia un lado.","cat":1},
{"n":"Patada de glúteo en cuadrupedia","g":"Isquio y glúteo","lv":" ","i":"Glute_Kickback","q":"patada de gluteo cuadrupedia tecnica","c":"En cuadrupedia con la espalda neutra, lleva una pierna hacia atrás y arriba doblada a 90 grados. Aprieta el glúteo arriba y baja sin apoyar la rodilla. No arquees la espalda baja para subir más.","cat":1},
{"n":"Patada de glúteo en polea","g":"Isquio y glúteo","lv":" ","i":"One-Legged_Cable_Kickback","q":"patada de gluteo en polea tobillera tecnica","c":"Con la tobillera en polea baja y agarrado del marco, lleva la pierna hacia atrás en arco hasta donde puedas sin arquear la espalda. Aprieta el glúteo y regresa lento. Mantén el abdomen firme y la cadera cuadrada.","cat":1},
{"n":"Curl femoral de pie (máquina)","g":"Isquio y glúteo","lv":" ","i":"Standing_Leg_Curl","q":"curl femoral de pie maquina una pierna tecnica","c":"Inclina un poco el torso hacia delante con el cojín en la parte trasera de la pierna. Flexiona la rodilla llevando el talón hacia el glúteo, pausa y baja lento. No levantes la cadera ni uses impulso.","cat":1},
{"n":"Peso muerto sumo","g":"Isquio y glúteo","lv":" ","i":"Sumo_Deadlift","q":"peso muerto sumo tecnica","c":"Pies muy abiertos, puntas afuera y agarre entre las piernas con los brazos verticales. Empuja el piso con los pies manteniendo el pecho arriba y la barra pegada al cuerpo. Evita redondear la espalda al despegar la barra.","cat":1},
{"n":"Pull through en polea","g":"Isquio y glúteo","lv":" ","i":"Pull_Through","q":"pull through polea baja gluteo tecnica","c":"De espaldas a la polea baja y con la cuerda entre las piernas, empuja la cadera hacia atrás con las rodillas ligeramente flexionadas. Sube extendiendo la cadera y aprieta los glúteos. Los brazos solo sujetan, no jalan.","cat":1},
{"n":"Peso muerto rumano con barra","g":"Isquio y glúteo","lv":" ","i":"Stiff-Legged_Barbell_Deadlift","q":"peso muerto rumano con barra tecnica","c":"Con las rodillas casi fijas y ligeramente flexionadas, lleva la cadera hacia atrás y baja la barra pegada a las piernas hasta sentir el estiramiento en el femoral. Sube extendiendo la cadera. La espalda siempre recta.","cat":1},
{"n":"Peso muerto rumano en Smith","g":"Isquio y glúteo","lv":" ","i":"Smith_Machine_Stiff-Legged_Deadlift","q":"peso muerto rumano en maquina smith tecnica","c":"Con la barra del Smith a media altura del muslo, lleva la cadera atrás y baja la barra pegada a las piernas. Sube extendiendo la cadera y aprieta los glúteos. Mantén la espalda recta y las rodillas apenas flexionadas.","cat":1},
{"n":"Elevación de talones de pie (mancuernas)","g":"Gemelo","lv":" ","i":"Standing_Dumbbell_Calf_Raise","q":"elevacion de talones de pie con mancuernas tecnica","c":"Con una mancuerna en cada mano y la punta de los pies sobre una tarima, sube los talones lo más alto posible y pausa arriba. Baja hasta estirar bien el gemelo. Evita rebotar y mantén las rodillas casi extendidas.","cat":1},
{"n":"Elevación de talones en Smith","g":"Gemelo","lv":" ","i":"Smith_Machine_Calf_Raise","q":"elevacion de talones maquina smith gemelos tecnica","c":"Con la barra del Smith sobre los hombros y la punta de los pies sobre un disco, sube los talones al máximo y pausa. Baja hasta estirar el gemelo por completo. No rebotes y mantén las rodillas casi rectas.","cat":1},
{"n":"Gemelos en prensa","g":"Gemelo","lv":" ","i":"Calf_Press","q":"gemelos en prensa de piernas tecnica","c":"Sentado en la prensa con la punta de los pies en el borde inferior de la plataforma y las piernas casi extendidas, empuja con la punta hasta subir los talones. Pausa arriba y vuelve lento. Todo el movimiento sale del tobillo.","cat":1},
{"n":"Gemelo sentado a una pierna (mancuerna)","g":"Gemelo","lv":" ","i":"Dumbbell_Seated_One-Leg_Calf_Raise","q":"gemelo sentado una pierna con mancuerna tecnica","c":"Sentado con la punta de un pie sobre un bloque y una mancuerna apoyada sobre el muslo, sube el talón lo más alto posible. Pausa arriba y baja hasta estirar bien. No rebotes ni uses impulso del muslo.","cat":1},
{"n":"Elevación de talones de pie (barra)","g":"Gemelo","lv":" ","i":"Standing_Barbell_Calf_Raise","q":"elevacion de talones de pie con barra tecnica","c":"Con la barra sobre la parte alta de la espalda y la punta de los pies sobre una tarima, sube los talones al máximo y pausa. Baja hasta estirar el gemelo. Mantén el torso erguido y evita rebotar al bajar.","cat":1},
{"n":"Crunch abdominal","g":"Core","lv":" ","i":"Crunches","q":"crunch abdominal como se hace bien","c":"Acostado con las rodillas dobladas y las manos junto a la cabeza, despega los hombros del suelo contrayendo el abdomen y baja lento. Mantén la zona lumbar pegada y no jales del cuello con las manos.","cat":1},
{"n":"Crunch inverso","g":"Core","lv":" ","i":"Reverse_Crunch","q":"crunch inverso abdomen bajo tecnica","c":"Acostado con los brazos a los lados y las piernas flexionadas en el aire, lleva las rodillas al pecho enrollando la pelvis hacia atrás. Baja con control sin dejar caer las piernas. No te impulses con el torso ni balancees.","cat":1},
{"n":"Plancha lateral","g":"Core","lv":" ","i":"Side_Bridge","q":"plancha lateral tecnica oblicuos","c":"Apoya el antebrazo bajo el hombro y los pies uno sobre otro, y eleva la cadera hasta formar una línea recta de cabeza a tobillos. Mantén la posición respirando normal. No dejes caer la cadera ni gires el torso.","cat":1},
{"n":"Bicho muerto (dead bug)","g":"Core","lv":" ","i":"Dead_Bug","q":"dead bug ejercicio core tecnica","c":"Acostado con los brazos al techo y las caderas y rodillas a 90 grados, baja un brazo y la pierna contraria sin que se arquee la espalda baja. Vuelve y alterna. Mantén la zona lumbar pegada al suelo todo el tiempo.","cat":1},
{"n":"Press Pallof (polea)","g":"Core","lv":" ","i":"Pallof_Press","q":"press pallof polea anti rotacion tecnica","c":"De lado a la polea y con el agarre al pecho, estira los brazos al frente resistiendo que el cable te gire. Pausa y regresa al pecho. Mantén las caderas y los hombros cuadrados y el abdomen firme.","cat":1},
{"n":"Leñador en polea (de pie)","g":"Core","lv":" ","i":"Standing_Cable_Wood_Chop","q":"lenador en polea wood chop tecnica","c":"De lado a la polea alta, jala el cable en diagonal hacia abajo y al lado contrario, girando el torso y pivotando el pie. Regresa lento. Los brazos casi rectos y el movimiento sale del core, no de los brazos.","cat":1},
{"n":"Crunch en banco declinado","g":"Core","lv":" ","i":"Decline_Crunch","q":"crunch en banco declinado tecnica","c":"Asegura los pies en el banco declinado y cruza las manos sobre el pecho o junto a la cabeza. Enrolla el torso subiendo los hombros y baja lento sin soltarte del todo. No jales del cuello ni te balancees para subir.","cat":1},
{"n":"Crunch oblicuo","g":"Core","lv":" ","i":"Oblique_Crunches","q":"crunch oblicuo como se hace","c":"Acostado con los pies elevados y una mano tras la cabeza, sube el hombro hacia la rodilla contraria rotando el torso. Baja controlado y alterna lados. Evita jalar del cuello y mantén la espalda baja pegada.","cat":1},
{"n":"Inclinación lateral con mancuerna","g":"Core","lv":" ","i":"Dumbbell_Side_Bend","q":"inclinacion lateral con mancuerna oblicuos tecnica","c":"De pie con una mancuerna en una mano y la otra en la cintura, inclínate hacia el lado de la mancuerna y sube contrayendo el oblicuo opuesto. Mantén el torso en el mismo plano. No gires ni uses mucho peso.","cat":1},
{"n":"Bicicleta de aire","g":"Core","lv":" ","i":"Air_Bike","q":"bicicleta abdominal air bike tecnica","c":"Acostado con las manos junto a la cabeza y los hombros arriba, lleva un codo hacia la rodilla contraria mientras estiras la otra pierna. Alterna con ritmo controlado. No jales del cuello y mantén la espalda baja pegada.","cat":1},
{"n":"Rodillas al pecho en banco","g":"Core","lv":" ","i":"Flat_Bench_Leg_Pull-In","q":"rodillas al pecho en banco abdomen bajo tecnica","c":"Sentado al borde del banco, apoyado con las manos y las piernas estiradas, lleva las rodillas al pecho inclinando un poco el torso hacia atrás. Estira de nuevo sin tocar el suelo. No te balancees con el cuerpo.","cat":1}
];
